insert into public.issues (id, data) values ('i001', '{"code": "ISS-001", "created": 1790900000000, "description": "א. בנצ מרק סוכונות , יצרן , מוצר בצורה רוחבית\nב. מדרוג ( ציון ) משוקלל פנמי לסוכנות על פי מקטריונטים שאנו קובצעים משקלים להם \nג. בנצמרק תנאי מעסיקים רוחבי", "due": "", "opened": "", "owner": "", "resolution": "", "severity": "", "status": "open", "subject": "דש בורד כללי עד לרמת בקרה", "task": "", "type": "", "updated": 1790900000000}'::jsonb) on conflict (id) do update set data = excluded.data;
