insert into public.issues (id, data) values ('i003', '{"code": "ISS-003", "created": 1790900000000, "description": "א. תקלות ברמת עובד\nב. כמה עובדים עם כיסוי לאכע על רובד שכר בקרן פנסיה אבל מסלול קרן פנסיה פחות מ75% \nג. כמות עובדים שנטשו את מנהל ההסדר במעסיק\nד. איתור שיעורי הפקדה לא תקינים ( תיקון 16 , תקנה 19 , פיצויים, אכע מעל 2.5% מעסיק , מעביד מעל 7.5%)", "due": "", "opened": "", "owner": "", "resolution": "", "severity": "", "status": "open", "subject": "דש בורד מעסיק", "task": "", "type": "", "updated": 1790900000000}'::jsonb) on conflict (id) do update set data = excluded.data;
